import type { z } from "zod";
import type { VisualDnaSchema } from "./schema.js";

export type VisualDna = z.infer<typeof VisualDnaSchema>;
export type Moment = VisualDna["moments"][number];

/** Stored/served Visual DNA record. */
export interface VisualDnaRecord {
  id: string;
  trackRef: string;
  kind: "base" | "remix";
  parentId?: string;
  /** "claude" when generated by the model, "preset" when we fell back. */
  origin: "claude" | "preset";
  remixPrompt?: string;
  dna: VisualDna;
  createdAt: number;
}
